import{_ as t,o,c as r,a2 as e}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Подтверждения и доверие","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/approvals.md","filePath":"ru/guides/approvals.md","lastUpdated":1792323081000}'),s={name:"ru/guides/approvals.md"};function l(i,a,n,p,h,c){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="подтверждения-и-доверие" tabindex="-1">Подтверждения и доверие <a class="header-anchor" href="#подтверждения-и-доверие" aria-label="Permalink to &quot;Подтверждения и доверие&quot;">​</a></h1><p>Bot, который умеет писать файлы, выполнять команды и отправлять людям сообщения, нуждается в границе, которую вы действительно понимаете. Эта страница объясняет границу со стороны пользователя: до чего Bot может дотянуться, когда он останавливается и спрашивает, что подтверждение покрывает, а что нет. Механика — списки участников, режимы и правила — описана в <a href="./access.html">Контроле доступа</a>.</p><h2 id="что-bot-может-трогать-по-умолчанию" tabindex="-1">Что Bot может трогать по умолчанию <a class="header-anchor" href="#что-bot-может-трогать-по-умолчанию" aria-label="Permalink to &quot;Что Bot может трогать по умолчанию&quot;">​</a></h2><ul><li><strong>Собственное рабочее пространство — и ничего больше.</strong> Каждый Bot работает в своём изолированном контейнерном рабочем пространстве (<code>/data</code>). Файлы и состояние остаются там, и Bot не видят друг друга — см. <a href="./container.html">Рабочее пространство</a>.</li><li><strong>Только подключённые вами каналы и люди.</strong> Bot присутствует на платформе потому, что вы добавили её на вкладке <strong>Platforms</strong>, и отвечает конкретной идентичности потому, что это разрешает контроль доступа.</li><li><strong>Только тот уровень, который выдан каждому человеку.</strong> Доступ к рабочему пространству разделён на уровни (чат, чтение файлов, запись файлов, выполнение команд, управление), и задача получает нужный ей уровень — не больше. Уровни определены в <a href="./access.html">Контроле доступа</a>.</li></ul><p>Эти права берутся из двух списков участников на вкладке <strong>Access</strong> Bot: <strong>Channel Members</strong> (участники каналов) — для идентичностей на IM-платформах, <strong>Workspace Members</strong> (участники рабочего пространства) — для зарегистрированных пользователей Memoh.</p><h2 id="когда-он-вас-спрашивает" tabindex="-1">Когда он вас спрашивает <a class="header-anchor" href="#когда-он-вас-спрашивает" aria-label="Permalink to &quot;Когда он вас спрашивает&quot;">​</a></h2><p>Вызовы инструментов записи и выполнения могут требовать подтверждения человеком — это настраивается для каждого Bot на его вкладке <strong>Tool Approval</strong>. Когда инструмент настроен требовать подтверждения, порядок такой:</p><ol><li>Bot предлагает действие — конкретный вызов инструмента, до того как что-либо выполнится.</li><li>Вы подтверждаете или отклоняете его.</li><li>Выполняется только подтверждённый вызов; отклонённый не запускается никогда.</li></ol><p>Подтверждение всегда происходит до действия, поэтому просмотр запроса — это и есть ваш момент контроля, а не ликвидация последствий. Ожидающий запрос может и истечь по таймауту, а не ждать вечно; если вы его пропустили, попросите Bot повторить действие.</p><div class="tip custom-block"><p class="custom-block-title">Больше рубежей, если хочется</p><p>Помимо настроек <strong>Tool Approval</strong>, <a href="./hooks.html">хук</a>, сработавший на событии, может сам запросить подтверждение человека — удобно, когда нужно стеречь один конкретный шаблон команды, а не инструмент целиком.</p></div><h2 id="что-держать-за-подтверждением" tabindex="-1">Что держать за подтверждением <a class="header-anchor" href="#что-держать-за-подтверждением" aria-label="Permalink to &quot;Что держать за подтверждением&quot;">​</a></h2><p>Это рекомендации, а не значения по умолчанию, которые Memoh навязывает; считайте их разумной отправной точкой:</p><ul><li><strong>Сообщения, покидающие рабочее пространство</strong> — всё, что отправляется другим людям или публикуется открыто.</li><li><strong>Удаление и перезапись файлов</strong>, особенно тех, которые Bot не создавал.</li><li><strong>Установки и долго выполняющиеся команды</strong> в рабочем пространстве.</li><li><strong>Всё, что тратит деньги или касается продакшена.</strong></li></ul><p>Действия, не выходящие за пределы рабочего пространства Bot (черновики, наведение порядка, чтение), — первые кандидаты на освобождение от подтверждений. О том, как это встраивается в жизненный цикл рутины — от первого запуска только на чтение до расширения прав, — см. <a href="./working-with-bots.html">Работу с Bot</a>.</p><h2 id="перехват-управления-и-учетные-данные" tabindex="-1">Перехват управления и учётные данные <a class="header-anchor" href="#перехват-управления-и-учетные-данные" aria-label="Permalink to &quot;Перехват управления и учётные данные&quot;">​</a></h2><p>Когда Bot, работая на своём видимом рабочем столе, упирается в экран входа или CAPTCHA, вы перехватываете управление экраном и сами вводите пароль, passkey или одноразовый код, после чего возвращаете управление. Учётные данные идут с вашей клавиатуры прямо на сайт — сообщать их Bot не нужно вовсе.</p><p>Сессия браузера после этого остаётся в том же рабочем пространстве, так что последующие задачи выполняются уже под вашим входом, без повторного перехвата. См. <a href="./browser-computer-use.html">Browser / Computer Use</a> и <a href="./quick-start.html#шаг-5-даите-ему-рабочее-пространство-и-браузер">Быстрый старт</a>.</p><h2 id="честное-замечание-о-границе" tabindex="-1">Честное замечание о границе <a class="header-anchor" href="#честное-замечание-о-границе" aria-label="Permalink to &quot;Честное замечание о границе&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Чего подтверждение не делает</p><p>Подтверждение преграждает путь предложенному действию — оно не отменяет уже выполненную работу и не может отозвать уже отправленное сообщение. Отклонение запроса останавливает этот запрос; это не кнопка отката.</p></div><p>Поэтому действительно надёжная привычка — та же, что в <a href="./access.html">Контроле доступа</a>: выдать минимальный уровень, которого требует задача, просмотреть несколько запусков и расширять права потом. Доверие к Bot строится так же, как доверие к новому коллеге: постепенно, на фактах.</p>',20)])])}const m=t(s,[["render",l]]);export{u as __pageData,m as default};
